// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetHomePage Get the home page
	// (GET /v1/stores/{store_id}/storefront/home)
	GetHomePage(ctx context.Context, request GetHomePageRequestObject) (GetHomePageResponseObject, error)
	// SaveHomePage Save the home page
	// (PUT /v1/stores/{store_id}/storefront/home)
	SaveHomePage(ctx context.Context, request SaveHomePageRequestObject) (SaveHomePageResponseObject, error)
	// DeleteStoreLogo Remove the logo
	// (DELETE /v1/stores/{store_id}/storefront/logo)
	DeleteStoreLogo(ctx context.Context, request DeleteStoreLogoRequestObject) (DeleteStoreLogoResponseObject, error)
	// GetStoreLogo Get the logo and any upload in progress
	// (GET /v1/stores/{store_id}/storefront/logo)
	GetStoreLogo(ctx context.Context, request GetStoreLogoRequestObject) (GetStoreLogoResponseObject, error)
	// CreateLogoUpload Start a logo upload
	// (POST /v1/stores/{store_id}/storefront/logo/uploads)
	CreateLogoUpload(ctx context.Context, request CreateLogoUploadRequestObject) (CreateLogoUploadResponseObject, error)
	// CompleteLogoUpload Process an uploaded logo
	// (POST /v1/stores/{store_id}/storefront/logo/uploads/{asset_id}/complete)
	CompleteLogoUpload(ctx context.Context, request CompleteLogoUploadRequestObject) (CompleteLogoUploadResponseObject, error)
	// ListLandingPages List landing pages
	// (GET /v1/stores/{store_id}/storefront/pages)
	ListLandingPages(ctx context.Context, request ListLandingPagesRequestObject) (ListLandingPagesResponseObject, error)
	// CreateLandingPage Create a landing page
	// (POST /v1/stores/{store_id}/storefront/pages)
	CreateLandingPage(ctx context.Context, request CreateLandingPageRequestObject) (CreateLandingPageResponseObject, error)
	// DeleteLandingPage Delete a landing page
	// (DELETE /v1/stores/{store_id}/storefront/pages/{page_id})
	DeleteLandingPage(ctx context.Context, request DeleteLandingPageRequestObject) (DeleteLandingPageResponseObject, error)
	// GetLandingPage Get a landing page
	// (GET /v1/stores/{store_id}/storefront/pages/{page_id})
	GetLandingPage(ctx context.Context, request GetLandingPageRequestObject) (GetLandingPageResponseObject, error)
	// UpdateLandingPage Replace a landing page
	// (PUT /v1/stores/{store_id}/storefront/pages/{page_id})
	UpdateLandingPage(ctx context.Context, request UpdateLandingPageRequestObject) (UpdateLandingPageResponseObject, error)
	// ListPolicies List policies
	// (GET /v1/stores/{store_id}/storefront/policies)
	ListPolicies(ctx context.Context, request ListPoliciesRequestObject) (ListPoliciesResponseObject, error)
	// GetPolicy Get a policy
	// (GET /v1/stores/{store_id}/storefront/policies/{policy})
	GetPolicy(ctx context.Context, request GetPolicyRequestObject) (GetPolicyResponseObject, error)
	// SavePolicy Save a policy
	// (PUT /v1/stores/{store_id}/storefront/policies/{policy})
	SavePolicy(ctx context.Context, request SavePolicyRequestObject) (SavePolicyResponseObject, error)
	// ListSectionTypes List section types with their settings schemas
	// (GET /v1/stores/{store_id}/storefront/section-types)
	ListSectionTypes(ctx context.Context, request ListSectionTypesRequestObject) (ListSectionTypesResponseObject, error)
	// GetStorefrontTheme Get the theme
	// (GET /v1/stores/{store_id}/storefront/theme)
	GetStorefrontTheme(ctx context.Context, request GetStorefrontThemeRequestObject) (GetStorefrontThemeResponseObject, error)
	// UpdateStorefrontTheme Save the theme
	// (PUT /v1/stores/{store_id}/storefront/theme)
	UpdateStorefrontTheme(ctx context.Context, request UpdateStorefrontThemeRequestObject) (UpdateStorefrontThemeResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

